import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import {
  BlurStyle,
  Canvas,
  Group,
  Picture,
  PointMode,
  Skia,
  StrokeCap,
  TileMode,
  vec,
  type SkCanvas,
  type SkPicture,
} from "@shopify/react-native-skia";
import { FOLD_H, FOLD_W, staticScene, type Item } from "./foldDesign";
import { FoldController, type FoldEvent } from "./foldController";

export type OrigamiFoldHandle = {
  /** Play the last fold backwards. */
  undo: () => void;
  /** Unfold everything, one fold after another. */
  reset: () => void;
};

export type OrigamiFoldProps = {
  /** Width in layout points; the sheet keeps its 340 x 420 proportions. */
  width?: number;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Called when a fold lands or is undone, with the number of folds now on the paper. */
  onFoldsChange?: (folds: number) => void;
  /** Hook haptics here: 'grab', 'crease' (a fold lands, strength 0 to 1), 'release' and 'undo'. */
  onFeedback?: (event: FoldEvent, strength?: number) => void;
  label?: string;
  style?: ViewStyle;
};

function safeDispose(o: unknown): void {
  const d = (o as { dispose?: () => void } | null | undefined)?.dispose;
  if (typeof d === "function") {
    try {
      d.call(o);
    } catch {
      /* some hosts free these on their own */
    }
  }
}

/** Paint a draw list with Skia. */
function paintItems(canvas: SkCanvas, items: Item[]) {
  const paint = Skia.Paint();
  paint.setAntiAlias(true);
  const blurs = new Map<number, ReturnType<typeof Skia.MaskFilter.MakeBlur>>();
  for (const it of items) {
    if (it.k === "poly") {
      const path = Skia.Path.Make();
      path.moveTo(it.pts[0], it.pts[1]);
      for (let i = 2; i < it.pts.length; i += 2) path.lineTo(it.pts[i], it.pts[i + 1]);
      path.close();
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      let shader: ReturnType<typeof Skia.Shader.MakeLinearGradient> | null = null;
      if (it.grad) {
        shader = Skia.Shader.MakeLinearGradient(
          vec(it.grad.x0, it.grad.y0),
          vec(it.grad.x1, it.grad.y1),
          [Skia.Color(it.grad.c0), Skia.Color(it.grad.c1)],
          null,
          TileMode.Clamp,
        );
        paint.setShader(shader);
      }
      if (it.blur) {
        const key = Math.round(it.blur * 10);
        let f = blurs.get(key);
        if (!f) {
          f = Skia.MaskFilter.MakeBlur(BlurStyle.Normal, it.blur / 2, true);
          blurs.set(key, f);
        }
        paint.setMaskFilter(f);
      }
      paint.setAlphaf(it.alpha ?? 1);
      canvas.drawPath(path, paint);
      path.dispose?.();
      paint.setShader(null);
      safeDispose(shader);
    } else if (it.k === "dots") {
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      paint.setAlphaf(it.alpha);
      paint.setStrokeWidth(it.size);
      paint.setStrokeCap(StrokeCap.Square);
      const pts = [];
      for (let i = 0; i < it.pts.length; i += 2) pts.push(vec(it.pts[i], it.pts[i + 1]));
      canvas.drawPoints(PointMode.Points, pts, paint);
    } else {
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      paint.setAlphaf(it.alpha ?? 1);
      paint.setStrokeWidth(it.width);
      paint.setStrokeCap(StrokeCap.Round);
      canvas.drawLine(it.pts[0], it.pts[1], it.pts[2], it.pts[3], paint);
    }
  }
  blurs.forEach((f) => safeDispose(f));
  safeDispose(paint);
}


function record(items: Item[]): SkPicture {
  const rec = Skia.PictureRecorder();
  const canvas = rec.beginRecording(Skia.XYWHRect(0, 0, FOLD_W, FOLD_H));
  paintItems(canvas, items);
  return rec.finishRecordingAsPicture();
}

export const OrigamiFold = forwardRef<OrigamiFoldHandle, OrigamiFoldProps>(function OrigamiFold(
  {
    width = FOLD_W,
    slowMotion = false,
    reducedMotion,
    onFoldsChange,
    onFeedback,
    label = "A sheet of origami paper on a desk. Press anywhere on the paper and drag in any direction to fold it",
    style,
  },
  ref,
) {
  const scale = width / FOLD_W;
  const height = FOLD_H * scale;
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const ctl = useRef<FoldController | null>(null);
  if (!ctl.current) ctl.current = new FoldController();
  const c = ctl.current;
  c.slowMotion = slowMotion;
  c.reduced = reduce;
  c.onChange = onFoldsChange;
  c.onFeedback = onFeedback;
  const [back, setBack] = useState<SkPicture | null>(null);
  const [frame, setFrame] = useState<SkPicture | null>(null);

  useImperativeHandle(ref, () => ({ undo: () => c.undo(), reset: () => c.reset() }), [c]);

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  useEffect(() => {
    const pic = record(staticScene().back);
    setBack(pic);
    return () => {
      setTimeout(() => safeDispose(pic), 1500);
    };
  }, []);

  useEffect(() => {
    let alive = true;
    let last = 0;
    let prev: SkPicture | null = null;
    const retired: unknown[] = [];
    const loop = (now: number) => {
      if (!alive) return;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      if (c.update(dt) || !prev) {
        const pic = record(c.frame());
        setFrame(pic);
        if (prev) retired.push(prev);
        while (retired.length > 8) safeDispose(retired.shift());
        prev = pic;
      }
      requestAnimationFrame(loop);
    };
    const raf = requestAnimationFrame(loop);
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      const rest = [...retired, prev];
      setTimeout(() => rest.forEach(safeDispose), 1500);
    };
  }, [c]);

  const pan = useMemo(
    () =>
      PanResponder.create({
        // only a press that lands on the paper starts a fold
        onStartShouldSetPanResponder: (evt) => c.down(evt.nativeEvent.locationX / scale, evt.nativeEvent.locationY / scale),
        onPanResponderMove: (evt) => c.move(evt.nativeEvent.locationX / scale, evt.nativeEvent.locationY / scale),
        onPanResponderRelease: () => c.up(),
        onPanResponderTerminate: () => c.up(),
        onPanResponderTerminationRequest: () => false,
      }),
    [scale, c],
  );

  return (
    <View
      style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#1d1d21" }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      <Canvas pointerEvents="none" style={{ width, height }}>
        <Group transform={[{ scale }]}>
          {back ? <Picture picture={back} /> : null}
          {frame ? <Picture picture={frame} /> : null}
        </Group>
      </Canvas>
    </View>
  );
});

/* Origami fold geometry. Pure TypeScript, no dependencies.

   The sheet is a list of flat convex facets stacked in layers. A fold is a
   crease line anywhere on the sheet: every facet it crosses is cut in two and
   the side behind the crease swings over by pi, ending reflected, flipped and
   on top of the pile. Posing a cut at a fractional angle rotates just those
   facets about the crease, so the same data folds forward and unfolds back. */

export type P2 = [number, number];
export type V3 = [number, number, number];

export type Facet = { pts: P2[]; layer: number; flipped: boolean };
export type CutFacet = Facet & { move: boolean; layerAfter: number };

/** Fold the side where n.p < d over onto the side where n.p > d. */
export type Crease = { nx: number; ny: number; d: number };

/** Layer spacing in sheet units, so stacked paper never z-fights. */
export const THICK = 0.012;
/** How far a freely swinging flap lags then leads its crease (radians). */
const BEND = 0.2;

function area(pts: P2[]): number {
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    const [x0, y0] = pts[i];
    const [x1, y1] = pts[(i + 1) % pts.length];
    a += x0 * y1 - x1 * y0;
  }
  return a / 2;
}

/** Sutherland-Hodgman clip of a convex polygon to f(p) >= 0 (sign = 1) or f(p) <= 0 (sign = -1). */
function clip(pts: P2[], c: Crease, sign: 1 | -1): P2[] {
  const f = (p: P2) => sign * (c.nx * p[0] + c.ny * p[1] - c.d);
  const out: P2[] = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    const fa = f(a);
    const fb = f(b);
    if (fa >= -1e-9) out.push(a);
    if ((fa > 1e-9 && fb < -1e-9) || (fa < -1e-9 && fb > 1e-9)) {
      const t = fa / (fa - fb);
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    }
  }
  return out;
}

function reflect(p: P2, c: Crease): P2 {
  const s = c.nx * p[0] + c.ny * p[1] - c.d;
  return [p[0] - 2 * s * c.nx, p[1] - 2 * s * c.ny];
}

export type Sheet = Facet[];
export const flatSheet = (): Sheet => [{ pts: [[-1, -1], [1, -1], [1, 1], [-1, 1]], layer: 0, flipped: false }];
/** Facets beyond this and further folds are refused, to keep frames cheap. */
export const MAX_FACETS = 260;

/** Split the sheet along the crease. Returns null when the crease misses the paper (nothing to fold). */
export function cutSheet(sheet: Sheet, c: Crease): CutFacet[] | null {
  const stay: Facet[] = [];
  const move: Facet[] = [];
  for (const f of sheet) {
    const a = clip(f.pts, c, 1);
    const b = clip(f.pts, c, -1);
    if (a.length >= 3 && Math.abs(area(a)) > 1e-7) stay.push({ pts: a, layer: f.layer, flipped: f.flipped });
    if (b.length >= 3 && Math.abs(area(b)) > 1e-7) move.push({ pts: b, layer: f.layer, flipped: f.flipped });
  }
  if (!stay.length || !move.length || stay.length + move.length > MAX_FACETS) return null;
  const top = Math.max(...stay.map((f) => f.layer), ...move.map((f) => f.layer));
  const maxMove = Math.max(...move.map((f) => f.layer));
  return [
    ...stay.map((f) => ({ ...f, move: false, layerAfter: f.layer })),
    ...move.map((f) => ({ ...f, move: true, layerAfter: top + 1 + (maxMove - f.layer) })),
  ];
}

/** The flat sheet after the cut has been folded all the way over. */
export function applyCut(cuts: CutFacet[], c: Crease): Sheet {
  const out: Facet[] = cuts.map((f) =>
    f.move
      ? // reflecting reverses the winding, so reverse the points to keep them counter-clockwise
        { pts: f.pts.map((p) => reflect(p, c)).reverse(), layer: f.layerAfter, flipped: !f.flipped }
      : { pts: f.pts, layer: f.layer, flipped: f.flipped },
  );
  // keep layer numbers dense so a long session never stacks the paper up into the sky
  const ranks = Array.from(new Set(out.map((f) => f.layer))).sort((x, y) => x - y);
  return out.map((f) => ({ ...f, layer: ranks.indexOf(f.layer) }));
}

export const ease = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * t * (t * (t * 6 - 15) + 10));

export type PosedFacet = {
  /** Vertices in sheet space: x right, y away from the viewer, z up. */
  pts: V3[];
  /** Unit normal of the side that shows colour A, per vertex. */
  normals: V3[];
  flipped: boolean;
  moving: boolean;
  layer: number;
  /** Rotation angle of the moving flap, 0 to pi; 0 for pieces that stay put. */
  phi: number;
  /** Distance of each vertex from the crease, for shading ramps. */
  dist: number[];
  /** Height of the pile the flap lands on (sheet units). */
  floor: number;
};

/** Pose a cut sheet with its flap swung to angle phi (0 flat, pi folded over). */
export function poseCuts(cuts: CutFacet[], c: Crease, phiIn: number): PosedFacet[] {
  const phi = Math.max(0, Math.min(Math.PI, phiIn));
  const out: PosedFacet[] = [];
  for (const f of cuts) {
    const zb = f.layer * THICK;
    const za = f.layerAfter * THICK;
    const sz = f.flipped ? -1 : 1;
    if (!f.move) {
      out.push({
        pts: f.pts.map((p) => [p[0], p[1], zb] as V3),
        normals: f.pts.map(() => [0, 0, sz] as V3),
        flipped: f.flipped,
        moving: false,
        layer: f.layer,
        phi: 0,
        dist: f.pts.map((p) => Math.abs(c.nx * p[0] + c.ny * p[1] - c.d)),
        floor: zb,
      });
      continue;
    }
    const pts: V3[] = [];
    const normals: V3[] = [];
    const dist: number[] = [];
    for (const p of f.pts) {
      const uAlong = c.nx * p[0] + c.ny * p[1] - c.d; // negative on the moving side
      const dd = Math.abs(uAlong);
      const pv = phi - BEND * Math.sin(2 * phi) * Math.min(1, dd / 1.3);
      const cv = Math.cos(pv);
      const sv = Math.sin(pv);
      const lift = zb + (za - zb) * (phi / Math.PI);
      // base point on the crease, then swing about it
      const bx = p[0] - uAlong * c.nx;
      const by = p[1] - uAlong * c.ny;
      pts.push([bx + uAlong * cv * c.nx, by + uAlong * cv * c.ny, lift - uAlong * sv]);
      normals.push([sz * sv * c.nx, sz * sv * c.ny, sz * cv]);
      dist.push(dd);
    }
    out.push({ pts, normals, flipped: f.flipped, moving: true, layer: f.layer, phi, dist, floor: 0 });
  }
  // the flap lands on whatever stays: record the pile height under it
  const stayTop = Math.max(0, ...out.filter((f) => !f.moving).map((f) => f.floor));
  for (const f of out) if (f.moving) f.floor = stayTop;
  return out;
}

export const facetArea = (f: Facet) => Math.abs(area(f.pts));

/** The sheet lying flat, nothing moving. */
export function poseFlat(sheet: Sheet): PosedFacet[] {
  return sheet.map((f) => ({
    pts: f.pts.map((p) => [p[0], p[1], f.layer * THICK] as V3),
    normals: f.pts.map(() => [0, 0, f.flipped ? -1 : 1] as V3),
    flipped: f.flipped,
    moving: false,
    layer: f.layer,
    phi: 0,
    dist: f.pts.map(() => 1.2),
    floor: f.layer * THICK,
  }));
}

export const sheetArea = (sheet: Sheet) => sheet.reduce((t, f) => t + facetArea(f), 0);

export function pointInFacet(p: P2, pts: P2[]): boolean {
  let sg = 0;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length];
    const cr = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]);
    if (Math.abs(cr) < 1e-12) continue;
    if (sg === 0) sg = Math.sign(cr);
    else if (Math.sign(cr) !== sg) return false;
  }
  return true;
}

/* Free-form folding controller. Pure TypeScript: press anywhere on the paper
   and drag in any direction. The crease sits halfway between where you grabbed
   and where your finger is, so it follows the finger. The grabbed part lifts
   and swings over; let go past the halfway mark and it lands, otherwise it
   springs back. Both the Skia component and the web preview drive this class. */
import {
  applyCut, cutSheet, flatSheet, poseCuts, poseFlat, pointInFacet,
  type Crease, type CutFacet, type P2, type Sheet,
} from "./foldMath";
import { buildFrame, flatView, screenToSheet, viewFor, type Item, type View } from "./foldDesign";

/** How far from the grab point the crease stays while the flap is still lifting (sheet units). */
const LIFT_REACH = 0.34;
/** Finger travel before a fold starts (sheet units). */
const DEAD = 0.035;
const PI = Math.PI;

type Active = {
  cuts: CutFacet[];
  crease: Crease;
  phi: number;
  target: number;
  v: number;
  held: boolean;
  /** An undo plays the committed fold backwards. */
  undo: boolean;
};

export type FoldEvent = "grab" | "crease" | "release" | "undo";

export class FoldController {
  sheet: Sheet = flatSheet();
  history: { sheet: Sheet; crease: Crease }[] = [];
  view: View = flatView();
  slowMotion = false;
  reduced = false;
  onChange?: (folds: number) => void;
  onFeedback?: (e: FoldEvent, strength?: number) => void;
  private act: Active | null = null;
  private grab: { p: P2; vx: number; vt: number; speed: number } | null = null;
  private lastSent = 0;
  private pendingUndo = 0;
  private dirty = true;

  get folds() { return this.history.length; }
  get busy() { return !!this.act; }

  /** Screen point (in the 340 x 420 frame) to sheet coordinates. */
  private toSheet(x: number, y: number): P2 { return screenToSheet(x, y, this.view); }

  down(x: number, y: number): boolean {
    if (this.act || this.reduced) return false;
    const p = this.toSheet(x, y);
    if (!this.sheet.some((f) => pointInFacet(p, f.pts))) return false;
    this.grab = { p, vx: 0, vt: performance.now(), speed: 0 };
    this.onFeedback?.("grab", 0.3);
    return true;
  }

  move(x: number, y: number) {
    const g = this.grab;
    if (!g) return;
    const f = this.toSheet(x, y);
    const dx = f[0] - g.p[0];
    const dy = f[1] - g.p[1];
    const dist = Math.hypot(dx, dy);
    if (dist < DEAD) { if (this.act?.held) { this.act.phi = 0; this.dirty = true; } return; }
    const nx = dx / dist;
    const ny = dy / dist;
    const a = Math.max(dist / 2, LIFT_REACH);
    const crease: Crease = { nx, ny, d: nx * g.p[0] + ny * g.p[1] + a };
    const phi = dist >= 2 * LIFT_REACH ? PI : Math.acos(Math.max(-1, 1 - dist / LIFT_REACH));
    const now = performance.now();
    const rate = (phi - (this.act?.phi ?? 0)) / Math.max(0.001, (now - g.vt) / 1000);
    g.speed = g.speed * 0.6 + rate * 0.4;
    g.vt = now;
    const cuts = cutSheet(this.sheet, crease);
    if (!cuts) { this.act = null; this.dirty = true; return; }
    this.act = { cuts, crease, phi, target: PI, v: 0, held: true, undo: false };
    // a soft tick when the flap passes upright
    if ((phi > PI / 2) !== (this.lastSent > PI / 2)) this.onFeedback?.("crease", 0.25);
    this.lastSent = phi;
    this.dirty = true;
  }

  up() {
    const g = this.grab;
    this.grab = null;
    const a = this.act;
    if (!a || !a.held) return;
    a.held = false;
    const flick = g ? g.speed : 0;
    a.target = a.phi > 0.62 * PI || (flick > 5 && a.phi > 0.4 * PI) ? PI : 0;
    a.v = Math.max(-8, Math.min(8, (g?.speed ?? 0) * 0.5));
    this.onFeedback?.("release", Math.min(1, Math.abs(a.v) / 6));
  }

  /** Play the last fold backwards. */
  undo(): boolean {
    if (this.act || !this.history.length) return false;
    const h = this.history.pop()!;
    this.sheet = h.sheet;
    const cuts = cutSheet(h.sheet, h.crease)!;
    this.act = { cuts, crease: h.crease, phi: PI, target: 0, v: 0, held: false, undo: true };
    this.onFeedback?.("undo", 0.3);
    this.onChange?.(this.history.length);
    this.dirty = true;
    return true;
  }

  reset() {
    if (this.act && !this.act.undo) { this.act = null; this.grab = null; }
    this.pendingUndo = this.history.length;
    if (!this.act) {
      this.undo();
      this.pendingUndo = Math.max(0, this.pendingUndo - 1);
    }
  }

  /** Jump to a given list of creases, folded fully. For tests and the cover image. */
  foldAll(creases: Crease[]) {
    for (const c of creases) {
      const cuts = cutSheet(this.sheet, c);
      if (!cuts) continue;
      this.history.push({ sheet: this.sheet, crease: c });
      this.sheet = applyCut(cuts, c);
    }
    this.dirty = true;
  }

  /** Hold a fold part way for a still frame. */
  hold(crease: Crease, phi: number) {
    const cuts = cutSheet(this.sheet, crease);
    if (cuts) this.act = { cuts, crease, phi, target: phi, v: 0, held: true, undo: false };
    this.dirty = true;
  }

  /** Advance the simulation. Returns true when the frame changed. */
  update(dt: number): boolean {
    const a = this.act;
    let changed = this.dirty;
    this.dirty = false;
    if (a && !a.held) {
      if (this.reduced) { a.phi = a.target; a.v = 0; }
      else {
        // a lightly under-damped spring: the flap settles with a small, soft overshoot
        const k = 90, c = 2 * Math.sqrt(k) * 0.78;
        const h = dt * (this.slowMotion ? 0.25 : 1);
        const n = Math.max(1, Math.ceil(h / 0.004));
        for (let i = 0; i < n; i++) {
          const acc = k * (a.target - a.phi) - c * a.v;
          a.v += (acc * h) / n;
          a.phi += (a.v * h) / n;
        }
        a.phi = Math.max(0, Math.min(PI, a.phi));
        if (a.phi >= PI && a.v > 0) a.v = 0;
        if (a.phi <= 0 && a.v < 0) a.v = 0;
      }
      changed = true;
      if (Math.abs(a.target - a.phi) < 0.004 && Math.abs(a.v) < 0.06) {
        a.phi = a.target;
        this.act = null;
        if (!a.undo && a.target === PI) {
          this.history.push({ sheet: this.sheet, crease: a.crease });
          this.sheet = applyCut(a.cuts, a.crease);
          this.onFeedback?.("crease", Math.min(1, 0.45 + Math.abs(a.v) * 0.1));
          this.onChange?.(this.history.length);
        }
        if (this.pendingUndo > 0) { this.pendingUndo--; this.undo(); }
      }
    }
    // the camera glides to frame whatever is on the table
    const tv = viewFor(this.posed());
    const k = this.reduced ? 1 : 1 - Math.exp(-dt * 7);
    const dv = Math.abs(tv.cx - this.view.cx) + Math.abs(tv.cy - this.view.cy) + Math.abs(tv.zoom - this.view.zoom);
    if (dv > 1e-4) {
      this.view = { cx: this.view.cx + (tv.cx - this.view.cx) * k, cy: this.view.cy + (tv.cy - this.view.cy) * k, zoom: this.view.zoom + (tv.zoom - this.view.zoom) * k };
      changed = true;
    }
    return changed;
  }

  private posed() {
    return this.act ? poseCuts(this.act.cuts, this.act.crease, this.act.phi) : poseFlat(this.sheet);
  }

  frame(): Item[] {
    return buildFrame(this.posed(), this.view);
  }
}

/* Camera, lighting and the draw list for Origami Fold. Pure TypeScript: the
   same list is painted by the Skia component and by the web Canvas2D preview. */
import type { PosedFacet, V3 } from "./foldMath";

export const FOLD_W = 340;
export const FOLD_H = 420;
/** Half the sheet edge in world units. */
const S = 3.4;

export type Item =
  | { k: "poly"; pts: number[]; color: string; alpha?: number; blur?: number; grad?: { x0: number; y0: number; x1: number; y1: number; c0: string; c1: string } }
  | { k: "dots"; pts: number[]; color: string; size: number; alpha: number }
  | { k: "line"; pts: number[]; color: string; width: number; alpha?: number };

/* ---------- camera: sheet x right, y away, z up -> world [x, z, -y] ---------- */
const EYE: V3 = [0, 13.5, 8.4];
const TARGET: V3 = [0, 0, -0.2];
const FOCAL = 520;
const CX = FOLD_W / 2;
const CY = FOLD_H * 0.5;

const sub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const unit = (a: V3): V3 => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};
const FWD = unit(sub(TARGET, EYE));
const RIGHT = unit(cross(FWD, [0, 1, 0]));
const UPV = cross(RIGHT, FWD);
const TO_CAM = unit(sub(EYE, [0, 0, 0])); // world space

/* The camera follows the folded shape: it recentres and zooms as the sheet shrinks. */
export type View = { cx: number; cy: number; zoom: number };
const VIEW: View = { cx: 0, cy: 0, zoom: 1 };
export const flatView = (): View => ({ cx: 0, cy: 0, zoom: 1 });
/** The view that frames a posed sheet. */
export function viewFor(facets: PosedFacet[]): View {
  let x0 = 9, x1 = -9, y0 = 9, y1 = -9;
  for (const f of facets) for (const p of f.pts) { x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]); }
  if (x1 < x0) return flatView();
  const e = Math.max(x1 - x0, y1 - y0) / 2;
  return { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, zoom: Math.max(0.55, Math.min(1.5, 1 / e)) };
}
/** Sheet-plane point under a screen point (the sheet lies on the table, z = 0). */
export function screenToSheet(x: number, y: number, v: View): [number, number] {
  const k = (x - CX) / FOCAL;
  const m = (y - CY) / FOCAL;
  const dir: V3 = [FWD[0] + k * RIGHT[0] - m * UPV[0], FWD[1] + k * RIGHT[1] - m * UPV[1], FWD[2] + k * RIGHT[2] - m * UPV[2]];
  const t = -EYE[1] / dir[1];
  const w: V3 = [EYE[0] + dir[0] * t, 0, EYE[2] + dir[2] * t];
  return [w[0] / (v.zoom * S) + v.cx, -w[2] / (v.zoom * S) + v.cy];
}
const world = (p: V3): V3 => [(p[0] - VIEW.cx) * VIEW.zoom * S, p[2] * VIEW.zoom * S, -(p[1] - VIEW.cy) * VIEW.zoom * S];
function proj(w: V3): [number, number, number] {
  const d = sub(w, EYE);
  const z = dot(d, FWD);
  const s = FOCAL / z;
  return [CX + dot(d, RIGHT) * s, CY - dot(d, UPV) * s, z];
}
const screen = (p: V3) => proj(world(p));

/* ---------- light ---------- */
// Light direction in sheet space (towards the light): from the front-left, high.
const LIGHT: V3 = unit([-0.45, -0.5, 1]);
// The same direction in world space for normals
const LIGHT_W: V3 = [LIGHT[0], LIGHT[2], -LIGHT[1]];
const FRONT_COL: [number, number, number] = [226, 66, 44]; // vermilion
const BACK_COL: [number, number, number] = [238, 231, 214]; // cream

const clamp = (v: number) => Math.max(0, Math.min(255, Math.round(v)));
const rgb = (c: [number, number, number], k: number, add = 0) => `rgb(${clamp(c[0] * k + add)},${clamp(c[1] * k + add)},${clamp(c[2] * k + add)})`;

/* Paper is matte with a faint sheen. `n` is the unit normal (sheet space) of the
   colour-A side; whichever side faces the camera is the one we see. */
function shade(n: V3, floor: number, depth: number): { col: string; side: "A" | "B" } {
  const nw: V3 = [n[0], n[2], -n[1]];
  const facing = dot(nw, TO_CAM) >= 0;
  const sn: V3 = facing ? nw : [-nw[0], -nw[1], -nw[2]];
  const diff = Math.max(0, dot(sn, LIGHT_W));
  const h = unit([LIGHT_W[0] + TO_CAM[0], LIGHT_W[1] + TO_CAM[1], LIGHT_W[2] + TO_CAM[2]]);
  const spec = Math.pow(Math.max(0, dot(sn, h)), 22) * 0.1;
  // light that has to reach down into a pile is a little dimmer
  const occl = 1 - Math.min(0.2, depth * 0.9) * (1 - Math.min(1, floor * 20));
  const k = (0.5 + 0.62 * diff) * (0.96 + 0.04 * occl);
  const base = facing ? FRONT_COL : BACK_COL;
  return { col: rgb(base, k, spec * 255), side: facing ? "A" : "B" };
}

/* Project the sheet onto the table along the light, for the cast shadow. */
function castPts(f: PosedFacet, lift: number): number[] {
  const out: number[] = [];
  for (const v of f.pts) {
    const z = Math.max(0, v[2] - lift);
    const p: V3 = [v[0] + (LIGHT[0] / LIGHT[2]) * -z, v[1] + (LIGHT[1] / LIGHT[2]) * -z, lift];
    const s = screen(p);
    out.push(s[0], s[1]);
  }
  return out;
}

/** Everything that never changes: the desk, its light pool and grain. */
export function staticScene(): { back: Item[] } {
  const back: Item[] = [];
  back.push({ k: "poly", pts: [0, 0, FOLD_W, 0, FOLD_W, FOLD_H, 0, FOLD_H], color: "#2a2a2e", grad: { x0: 0, y0: 0, x1: 0, y1: FOLD_H, c0: "#34343a", c1: "#1d1d21" } });
  // soft pool of light from the lamp, falling off towards the lower right
  back.push({ k: "poly", pts: [0, 0, FOLD_W, 0, FOLD_W, FOLD_H, 0, FOLD_H], color: "#ffffff", alpha: 1, grad: { x0: 40, y0: 60, x1: 300, y1: 380, c0: "rgba(255,241,214,0.17)", c1: "rgba(255,241,214,0)" } });
  // fine desk grain
  let seed = 1234567;
  const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
  const pts: number[] = [];
  for (let i = 0; i < 340; i++) pts.push(rnd() * FOLD_W, rnd() * FOLD_H);
  back.push({ k: "dots", pts, color: "#ffffff", size: 1, alpha: 0.045 });
  const dark: number[] = [];
  for (let i = 0; i < 260; i++) dark.push(rnd() * FOLD_W, rnd() * FOLD_H);
  back.push({ k: "dots", pts: dark, color: "#000000", size: 1, alpha: 0.12 });
  return { back };
}

const dir2 = (a: number[], i: number, j: number) => [a[j] - a[i], a[j + 1] - a[i + 1]];

/** One frame of the posed sheet. */
export function buildFrame(facets: PosedFacet[], view: View): Item[] {
  VIEW.cx = view.cx; VIEW.cy = view.cy; VIEW.zoom = view.zoom;
  const items: Item[] = [];
  // Cast shadow on the desk: a wide soft one and a tight contact one.
  for (const f of facets) {
    if (f.pts.length < 3) continue;
    const high = Math.max(...f.pts.map((v) => v[2]));
    items.push({ k: "poly", pts: castPts(f, 0), color: "#000000", alpha: Math.max(0.1, 0.34 - high * 0.12), blur: 12 + high * 20 });
  }
  for (const f of facets) {
    if (f.pts.length < 3 || f.moving) continue;
    items.push({ k: "poly", pts: castPts(f, 0), color: "#000000", alpha: 0.26, blur: 3 });
  }
  // Painter's order: farther from the camera first.
  const order = facets
    .map((f) => {
      const c = f.pts.reduce((a, v) => [a[0] + v[0] / f.pts.length, a[1] + v[1] / f.pts.length, a[2] + v[2] / f.pts.length] as V3, [0, 0, 0] as V3);
      return { f, depth: screen(c)[2] - c[2] * 0.0 + 0 };
    })
    .sort((a, b) => b.depth - a.depth);
  // Piles read by height, so when two facets sit near the same depth, lower layers come first.
  order.sort((a, b) => {
    const za = a.f.pts.reduce((m, v) => m + v[2], 0) / a.f.pts.length;
    const zb = b.f.pts.reduce((m, v) => m + v[2], 0) / b.f.pts.length;
    if (Math.abs(a.depth - b.depth) < 0.35) return za - zb;
    return b.depth - a.depth;
  });
  for (const { f } of order) {
    if (f.pts.length < 3) continue;
    const sp: number[] = [];
    for (const v of f.pts) {
      const s = screen(v);
      sp.push(s[0], s[1]);
    }
    if (f.moving) {
      // the flap shades the paper it swings over
      const high = Math.max(...f.pts.map((v) => v[2]));
      const lift = f.floor + 0.004;
      items.push({ k: "poly", pts: castPts(f, lift), color: "#3a0f06", alpha: Math.min(0.32, 0.08 + high * 0.2) * Math.min(1, Math.sin(f.phi) * 3 + 0.2), blur: 6 + high * 10 });
    }
    // vertex colours -> one gradient from the crease side to the far side
    const cols = f.pts.map((v, i) => shade(f.normals[i], f.moving ? 0 : v[2], f.dist[i]));
    const cen = f.pts.reduce((a, v) => [a[0] + v[0] / f.pts.length, a[1] + v[1] / f.pts.length], [0, 0]);
    const fall = 1.05 - 0.07 * Math.min(1.6, Math.hypot(cen[0] + 0.5, cen[1] - 0.2));
    let lo = 0;
    let hi = 0;
    f.dist.forEach((d, i) => {
      if (d < f.dist[lo]) lo = i;
      if (d > f.dist[hi]) hi = i;
    });
    // when the visible side changes across the facet, keep the dominant one flat
    const mid = shade(f.normals[0], f.moving ? 0 : f.pts[0][2], f.dist[0]);
    const flat = !f.moving || cols.some((c) => c.side !== cols[0].side) || hi === lo;
    const item: Item = { k: "poly", pts: sp, color: flat ? mid.col : cols[lo].col };
    if (flat) {
      // a faint sheen across a flat piece keeps big areas of paper from looking printed
      let l = 0, r = 0;
      for (let i = 0; i < f.pts.length; i++) { if (sp[i * 2] < sp[l * 2]) l = i; if (sp[i * 2] > sp[r * 2]) r = i; }
      const m = mid.col.match(/\d+/g)!.map(Number);
      const tone = (k: number) => `rgb(${clamp(m[0] * k)},${clamp(m[1] * k)},${clamp(m[2] * k)})`;
      item.grad = { x0: sp[l * 2], y0: sp[l * 2 + 1], x1: sp[r * 2], y1: sp[r * 2 + 1], c0: tone(fall * 0.97), c1: tone(fall * 1.03) };
    }
    if (!flat) item.grad = { x0: sp[lo * 2], y0: sp[lo * 2 + 1], x1: sp[hi * 2], y1: sp[hi * 2 + 1], c0: cols[lo].col, c1: cols[hi].col };
    items.push(item);
    // creases and paper edge
    for (let i = 0; i < f.pts.length; i++) {
      const j = (i + 1) % f.pts.length;
      // the crease being folded right now only shows once the paper starts to bend
      const live = f.dist[i] < 1e-6 && f.dist[j] < 1e-6;
      items.push({ k: "line", pts: [sp[i * 2], sp[i * 2 + 1], sp[j * 2], sp[j * 2 + 1]], color: "#2b0a04", width: 0.7, alpha: 0.28 * (live ? Math.min(1, f.phi * 4) : 1) });
    }
    // a light edge on the lit lip of a lifted flap sells the paper thickness
    if (f.moving && Math.sin(f.phi) > 0.05) {
      const a = f.dist.map((d, i) => ({ d, i })).sort((p, q) => p.d - q.d).slice(0, 2);
      if (a.length === 2 && a[1].d < 1e-6) {
        items.push({ k: "line", pts: [sp[a[0].i * 2], sp[a[0].i * 2 + 1], sp[a[1].i * 2], sp[a[1].i * 2 + 1]], color: "#fff4e6", width: 1, alpha: 0.35 });
      }
    }
  }
  void dir2;
  return items;
}

import React, { useRef, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { OrigamiFold, type OrigamiFoldHandle } from "./OrigamiFold";
import type { FoldEvent } from "./foldController";

export default function Example({ onFeedback }: { onFeedback?: (event: FoldEvent, strength?: number) => void }) {
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState(false);
  const [folds, setFolds] = useState(0);
  const paper = useRef<OrigamiFoldHandle>(null);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <OrigamiFold ref={paper} slowMotion={slow} reducedMotion={reduce} onFoldsChange={setFolds} onFeedback={onFeedback} />
      <Text accessibilityLiveRegion="polite" style={{ fontSize: 15, color: "#1f3a2a", fontFamily: "Geist-Regular", minHeight: 20 }}>
        {folds === 0 ? "Press the paper and drag any way to fold it" : `${folds} fold${folds === 1 ? "" : "s"}`}
      </Text>
      <View style={{ flexDirection: "row", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
        <Pressable accessibilityRole="button" accessibilityState={{ disabled: folds === 0 }} onPress={() => paper.current?.undo()} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Undo</Text>
        </Pressable>
        <Pressable accessibilityRole="button" accessibilityState={{ disabled: folds === 0 }} onPress={() => paper.current?.reset()} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Reset</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
    </View>
  );
}
